(function(){
  let out=[];
  // walk comment nodes
  let it=document.createNodeIterator(document.documentElement, NodeFilter.SHOW_COMMENT);
  let n; while(n=it.nextNode()){ out.push('COMMENT: '+n.nodeValue); }
  // meta tags
  document.querySelectorAll('meta').forEach(m=>out.push('META: '+m.outerHTML));
  // data attributes
  document.querySelectorAll('*').forEach(e=>{for(const a of e.attributes){if(a.name.startsWith('data-'))out.push('DATA: '+a.name+'='+a.value);}});
  return out.join('\n');
})()

(function(){
  const html=document.documentElement.outerHTML;
  // report structure without dumping raw, find token-like substrings
  const tokens=html.match(/[A-Za-z0-9_\-]{16,}/g)||[];
  return 'len='+html.length+' tokens='+JSON.stringify(tokens);
})()

